from pathlib import Path

import pytest

from axiom_prediction import cli, training
from axiom_prediction.split import ProblemSplit, split_key

# Generated by the original split.py at 25315d8, 2c73565, and 570613a.
@pytest.mark.parametrize("scheme, count, expected", [
    (3, 3, [2, 2, 0, 0, 0, 1, 2, 1]),
    (3, 10, [3, 3, 1, 7, 9, 8, 8, 7]),
    (3, 20, [6, 6, 0, 6, 2, 14, 7, 17]),
    (4, 3, [2, 2, 0, 1, 1, 1, 2, 1]),
    (4, 10, [3, 3, 1, 0, 0, 8, 8, 7]),
    (4, 20, [6, 6, 0, 15, 15, 14, 7, 17]),
    (5, 3, [1, 1, 2, 0, 0, 1, 2, 0]),
    (5, 10, [6, 6, 6, 6, 6, 2, 6, 5]),
    (5, 20, [6, 6, 16, 16, 16, 12, 6, 5]),
])
def test_historical_assignments(scheme, count, expected):
    names = [
        "ABC001+1.p", "ABC001-2.p", "ABC002+1.p",
        "struct_0__t3_struct_0.p", "struct_0__t4_struct_0.p",
        "tiny_theorem.p", "nested.name.p", "épreuve.p",
    ]
    split = ProblemSplit(count, scheme = scheme)
    assert list(map(split.part, names)) == expected
    assert [split.part(Path('/different/root') / name) for name in names] == expected

@pytest.mark.parametrize("scheme", [3, 4, 5])
def test_partition_and_metadata(scheme):
    names = [f"ABC{index:03d}+1.p" for index in range(100)]
    names += [f"article__t{index}.p" for index in range(100)]
    partitions = [ProblemSplit(10, [part], scheme) for part in range(10)]
    assert all(sum(split.contains(name) for split in partitions) == 1 for name in names)
    assert ProblemSplit(10, list(range(10)), scheme).select(names) == names
    assert all(ProblemSplit(scheme = scheme).part(name) == 0 for name in names)
    assert partitions[2].to_dict() == {"split": 10, "parts": [2], "scheme": scheme}
    assert f"scheme {scheme}" in partitions[2].describe()
    assert split_key("ABC001-2.p", scheme) == "ABC001"
    assert split_key("article__t1.p", scheme) == ("article__t1" if scheme == 3 else "article")

@pytest.mark.parametrize("scheme", [0, 1, 2, 6])
def test_unsupported_scheme(scheme):
    with pytest.raises(ValueError, match = "split-scheme"):
        ProblemSplit(scheme = scheme)

    with pytest.raises(SystemExit) as error:
        cli.build_parser().parse_args(["run", "--split-scheme", str(scheme)])

    assert error.value.code == 2

@pytest.mark.parametrize("scheme", [3, 4, 5])
def test_cli_training_held_out_scheme(tmp_path, monkeypatch, scheme):
    captured = {}
    def train(problems, **kwargs):
        captured.update(kwargs)
        return {}

    monkeypatch.setattr(training, "train_axiom_predictor", train)
    assert cli.main([
        "train", "--dataset", str(tmp_path / "dataset"), "--data-dir", str(tmp_path),
        "--split-scheme", str(scheme), "--split", "10", "--parts", "0",
        "--evaluate", "8", "--device", "cpu", "--no-wandb",
    ]) == 0
    assert captured["split"].to_dict() == {"split": 10, "parts": [0], "scheme": scheme}
    assert captured["evaluation_split"].to_dict() == {"split": 10, "parts": [8], "scheme": scheme}

@pytest.mark.parametrize("trained_scheme, eval_scheme, count, part, warns", [
    (3, 3, 10, 8, False), (4, 4, 10, 8, False), (5, 5, 10, 8, False),
    (3, 3, 10, 0, True), (4, 4, 10, 0, True), (5, 5, 10, 0, True),
    (3, 3, 20, 8, True), (4, 4, 20, 8, True), (5, 5, 20, 8, False),
    (3, 4, 10, 8, True), (4, 5, 10, 8, True), (5, 3, 10, 8, True),
    (None, 5, 10, 8, True), (2, 5, 10, 8, True),
])
def test_overlap_warnings(monkeypatch, trained_scheme, eval_scheme, count, part, warns):
    messages = []
    monkeypatch.setattr(training, "log_message", messages.append)
    trained = {"split": 10, "parts": [0], "scheme": trained_scheme}
    training.warn_on_training_overlap(
        {"split": trained}, ProblemSplit(count, [part], eval_scheme),
    )
    assert bool(messages) == warns

def test_training_rejects_different_evaluation_scheme(tmp_path):
    with pytest.raises(ValueError, match = "training split"):
        training.train_axiom_predictor(
            dataset = tmp_path, output_dir = tmp_path / "model",
            split = ProblemSplit(10, [0], 3), evaluation_split = ProblemSplit(10, [8], 4),
        )
